function renderAiChart() {
  const data = window._aiData || []
  aiChart?.setOption({
    tooltip: { trigger: 'item' },
    legend: { orient: 'vertical', left: 'left' },
    series: [{
      type: 'pie', radius: '60%',
      data: data.map(d => ({ name: d.model || d.MODEL, value: d.callCount || d.CALLCOUNT || 0 }))
    }]
  })
}
